// Builds ../data.js (airports, cities, route network) and ../map.js (world
// outline) for the Flight Stopovers app. Nothing here runs on deploy — run it
// by hand and commit the generated files.
//
//   mkdir -p /tmp/fso && cd /tmp/fso
//   for f in airports airlines routes; do
//     curl -sSO https://raw.githubusercontent.com/jpatokal/openflights/master/data/$f.dat
//   done
//   npm install world-atlas topojson-client
//   node <repo>/apps/flight-stopovers/build/build-data.js /tmp/fso
//
// Route data: OpenFlights (https://openflights.org/data), ODbL.
// Map outline: Natural Earth via world-atlas, public domain.
'use strict';
const fs = require('fs');
const path = require('path');

const src = path.resolve(process.argv[2] || '.');
const out = path.resolve(__dirname, '..');
const req = (m) => require(require.resolve(m, { paths: [src] }));
const topojson = req('topojson-client');

// OpenFlights .dat files are CSV with quoted strings and \N for null.
function parseCsv(file) {
  const rows = [];
  for (const line of fs.readFileSync(path.join(src, file), 'utf8').split('\n')) {
    if (!line.trim()) continue;
    const row = [];
    let cur = '', q = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (q) {
        if (c === '"' && line[i + 1] === '"') { cur += '"'; i++; }
        else if (c === '"') q = false;
        else cur += c;
      } else if (c === '"') q = true;
      else if (c === ',') { row.push(cur); cur = ''; }
      else cur += c;
    }
    row.push(cur);
    rows.push(row.map((v) => (v === '\\N' ? '' : v)));
  }
  return rows;
}

const airportsRaw = parseCsv('airports.dat');
const airlinesRaw = parseCsv('airlines.dat');
const routesRaw = parseCsv('routes.dat');

const byIata = new Map();
for (const r of airportsRaw) {
  const iata = r[4];
  if (!/^[A-Z]{3}$/.test(iata) || r[12] !== 'airport') continue;
  byIata.set(iata, { iata, name: r[1], city: r[2] || r[1], country: r[3], lat: +r[6], lon: +r[7] });
}
const airlineName = new Map();
for (const r of airlinesRaw) if (/^[A-Z0-9]{2}$/.test(r[3])) {
  if (!airlineName.has(r[3]) || r[7] === 'Y') airlineName.set(r[3], r[1]);
}

// Undirected, non-stop, airport-to-airport links with the airlines flying them.
const links = new Map();
for (const r of routesRaw) {
  const [al, , a, , b, , , stops] = r;
  if (stops !== '0' || a === b || !byIata.has(a) || !byIata.has(b)) continue;
  const key = a < b ? a + b : b + a;
  if (!links.has(key)) links.set(key, new Set());
  if (/^[A-Z0-9]{2}$/.test(al)) links.get(key).add(al);
}

const used = new Set();
for (const k of links.keys()) { used.add(k.slice(0, 3)); used.add(k.slice(3)); }
const airports = [...used].map((c) => byIata.get(c)).sort((x, y) => x.iata.localeCompare(y.iata));
const idx = new Map(airports.map((a, i) => [a.iata, i]));

const cityKey = (a) => a.city + '|' + a.country;
const cityList = [...new Set(airports.map(cityKey))].sort();
const cityIdx = new Map(cityList.map((c, i) => [c, i]));

const airlineCount = new Map();
for (const s of links.values()) for (const al of s) airlineCount.set(al, (airlineCount.get(al) || 0) + 1);
const airlineCodes = [...airlineCount.keys()].sort();
const alIdx = new Map(airlineCodes.map((c, i) => [c, i]));

// adj[i] = "j:a.b,j:a" in base36 — neighbour airport index and airline indices.
const adj = airports.map(() => []);
for (const [k, s] of links) {
  const i = idx.get(k.slice(0, 3)), j = idx.get(k.slice(3));
  const als = [...s].map((c) => alIdx.get(c).toString(36)).join('.');
  adj[i].push(j.toString(36) + ':' + als);
  adj[j].push(i.toString(36) + ':' + als);
}

const round = (n) => Math.round(n * 100) / 100;
const data = {
  source: 'OpenFlights route database (June 2014), ODbL',
  cities: cityList.map((c) => c.split('|')),
  airports: airports.map((a) => [a.iata, a.name, cityIdx.get(cityKey(a)), round(a.lat), round(a.lon)]),
  airlines: airlineCodes.map((c) => [c, airlineName.get(c) || c]),
  adj: adj.map((l) => l.join(',')),
};
fs.writeFileSync(path.join(out, 'data.js'),
  '// Generated by build/build-data.js — do not edit by hand.\n' +
  '// ' + data.source + '\n' +
  'window.FSO_DATA = ' + JSON.stringify(data) + ';\n');

// World outline as SVG path data in plain lon/lat degrees (y = -lat), so the
// app can draw it with an equirectangular projection and repeat it sideways.
const world = JSON.parse(fs.readFileSync(require.resolve('world-atlas/countries-50m.json', { paths: [src] }), 'utf8'));
const r1 = (n) => Math.round(n * 10) / 10;
function toPath(geom) {
  const rings = geom.type === 'Polygon' ? geom.coordinates : geom.coordinates.flat();
  let d = '';
  for (const ring of rings) {
    // Some rings (Russia, Fiji) cross the antimeridian. Keep their longitudes
    // continuous so the far part lands just past ±180° — the app draws the
    // world three times side by side, so it still shows up in the right place.
    let prev = '', lastX = ring[0][0];
    ring.forEach(([x, y], i) => {
      while (x - lastX > 180) x -= 360;
      while (x - lastX < -180) x += 360;
      lastX = x;
      const pt = r1(x) + ' ' + r1(-y);
      if (pt === prev) return;
      d += (i === 0 ? 'M' : ' ') + pt;
      prev = pt;
    });
    d += 'Z';
  }
  return d.replace(/ -/g, '-');
}
// Land is drawn country by country, and stroking those outlines gives both
// coastlines and borders. (Merging the countries into one land shape stitches
// Russia and Fiji back together across the antimeridian, which fills a band
// across the whole map.)
const land = world.objects.countries.geometries
  .map((g) => toPath(topojson.feature(world, g).geometry)).join('');
fs.writeFileSync(path.join(out, 'map.js'),
  '// Generated by build/build-data.js — do not edit by hand.\n' +
  '// Natural Earth 1:50m via world-atlas (public domain).\n' +
  'window.FSO_MAP = ' + JSON.stringify({ land }) + ';\n');

console.log(`${airports.length} airports, ${cityList.length} cities, ${links.size} links, ${airlineCodes.length} airlines`);
